#!/usr/bin/env node
// Brackenfield exercise kit. Every company, person, machine and number here is invented.
// Run: node brackenfield-kit.mjs            writes brackenfield-plant-register.xlsx here and serves FieldTrax on 127.0.0.1:8799
import http from 'node:http'; import { gunzipSync } from 'node:zlib'; import { writeFileSync } from 'node:fs';
const blob = JSON.parse(gunzipSync(Buffer.from("", 'base64')).toString());
writeFileSync('brackenfield-plant-register.xlsx', Buffer.from(blob.xlsx, 'base64'));
const PORT = Number(process.env.PORT || 8799), CLIENT = 'brackenfield', SECRET = 'not-a-real-secret';
let devices, readings, day, reqs, tokens;
function reset() { devices = structuredClone(blob.kit.devices); readings = structuredClone(blob.kit.readings); day = 0; reqs = 0; tokens = new Map(); }
reset();
const send = (res, code, body, h = {}) => { res.writeHead(code, { 'content-type': 'application/json', ...h }); res.end(JSON.stringify(body)); };
const when = (s) => Date.parse(s);
http.createServer((req, res) => {
  const u = new URL(req.url, 'http://x'); const p = u.pathname; let raw = '';
  req.on('data', (c) => raw += c); req.on('end', () => {
    if (p === '/__advance' && req.method === 'POST') {
      if (day > 0) return send(res, 409, { error: 'already_advanced', hint: 'POST /__reset to start over' });
      const a = blob.kit.advance; day = 1;
      const r = devices.find((d) => d.id === a.rename.id); r.name = a.rename.name;
      devices = devices.filter((d) => d.id !== a.gone); devices.push(structuredClone(a.add));
      for (const [id, l] of Object.entries(a.readings)) { readings[id] = (readings[id] || []).concat(l).sort((x, y) => when(x.time) - when(y.time)); }
      return send(res, 200, { ok: true, day });
    }
    if (p === '/__reset' && req.method === 'POST') { reset(); return send(res, 200, { ok: true }); }
    reqs++;
    if (reqs % 37 === 0) return send(res, 503, { error: 'upstream_unavailable' });
    if (reqs % 11 === 0) return send(res, 429, { error: 'rate_limited' }, { 'retry-after': '1' });
    if (p === '/oauth/token' && req.method === 'POST') {
      const f = new URLSearchParams(raw);
      if (f.get('client_id') !== CLIENT || f.get('client_secret') !== SECRET) return send(res, 401, { error: 'invalid_client' });
      const t = 'ftx_tok_' + Math.random().toString(36).slice(2); tokens.set(t, 40);
      return send(res, 200, { access_token: t, token_type: 'Bearer', expires_in_requests: 40 });
    }
    const t = (req.headers.authorization || '').replace('Bearer ', ''); const left = tokens.get(t);
    if (!left) return send(res, 401, { error: 'token_expired' });
    tokens.set(t, left - 1);
    let m;
    if (p === '/v2/assets') {
      const limit = Math.min(Number(u.searchParams.get('limit') || 25), 25), start = Number(u.searchParams.get('cursor') || 0);
      const items = devices.slice(start, start + limit);
      return send(res, 200, { items, next_cursor: start + limit < devices.length ? String(start + limit) : null });
    }
    if ((m = p.match(/^\/v2\/assets\/([^/]+)\/readings$/))) {
      if (!(m[1] in readings)) return send(res, 404, { error: 'not_found' });
      const limit = Math.min(Number(u.searchParams.get('limit') || 50), 50), start = Number(u.searchParams.get('cursor') || 0);
      const l = readings[m[1]], items = l.slice(start, start + limit);
      return send(res, 200, { items, next_cursor: start + limit < l.length ? String(start + limit) : null });
    }
    send(res, 404, { error: 'not_found' });
  });
}).listen(PORT, '127.0.0.1', () => console.log(`Wrote brackenfield-plant-register.xlsx\nFieldTrax on http://127.0.0.1:${PORT}  client_id=${CLIENT} client_secret=${SECRET}`));
